import { useState } from "react";

import { GoogleIcon } from "@huspy/shared-icons";
import { Button, Card, CardContent, CardHeader, CardTitle, cn, Separator } from "@huspy/shared-ui";

import { getEnvironmentLabel } from "./utils";

export function CreditOpsLoginPage() {
  const [status, setStatus] = useState<"idle" | "loading" | "error">("idle");
  const [error, setError] = useState<string | null>(null);
  const isLoading = status === "loading";

  const handleGoogleLogin = () => {
    try {
      setStatus("loading");
      setError(null);
      window.huspy.auth.login({ idpHint: "google", prompt: "login" });
    } catch (err) {
      setStatus("error");
      setError(err instanceof Error ? err.message : "Login failed. Please try again.");
    }
  };

  return (
    <div className="min-h-screen bg-white flex items-center justify-center p-4">
      <div className="max-w-xs">
        <Card className="bg-black border-0 shadow-xl">
          <CardHeader className="text-center pb-6">
            <CardTitle className="text-4xl font-bold text-white">
              Huspy<span className="text-sm relative -top-2.25">™</span>
              <br />
              Credit Ops
            </CardTitle>
          </CardHeader>

          <CardContent className="space-y-6">
            <div className="flex justify-center">
              <Button
                onClick={handleGoogleLogin}
                disabled={isLoading}
                className={cn(
                  "h-12 bg-white text-gray-900 hover:bg-gray-100 flex items-center justify-center gap-3 font-medium text-base border border-gray-200 shadow-sm px-8 cursor-pointer w-48 rounded-md",
                )}
              >
                <GoogleIcon className="h-5 w-5" />
                {isLoading ? "Logging in..." : "Log in with Google"}
              </Button>
            </div>

            {error && (
              <div className="p-3 bg-red-900/20 border border-red-700 rounded-md">
                <p className="text-red-300 text-sm">{error}</p>
              </div>
            )}

            <Separator className="bg-gray-700" />

            <div className="text-center">
              <p className="text-gray-400 text-sm">
                You are logging into:{" "}
                <p className="text-amber-300">{getEnvironmentLabel()} environment</p>
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
